function switchTab(tab) {
    $('.bt-w-menu p').removeClass('bgw');
    var tabIdx = {'list': 0, 'deploy': 1, 'logs': 2, 'readme': 3};
    $('.bt-w-menu p:eq('+tabIdx[tab]+')').addClass('bgw');
    $('.plugin-con').hide();

    if (tab === 'list') {
        $('#con-list').show();
        loadList();
    } else if (tab === 'deploy') {
        $('#con-deploy').show();
    } else if (tab === 'logs') {
        $('#con-logs').show();
        loadPluginLogs();
    } else if (tab === 'readme') {
        $('#con-readme').show();
    }
}

